// Real use case: private counter (like useState internally!)
function createCounter(initialValue = 0) {
  let count = initialValue; // Private variable

  return {
    increment: () => ++count,
    decrement: () => --count,
    reset: () => { count = initialValue; },
    getCount: () => count,
  };
}

