// ANY: dangerous — TypeScript trusts you blindly
function parseData(data: any) {
  console.log(data.name.toUpperCase()); // No error, but crashes at runtime!
}

// UNKNOWN: type-safe — must narrow before using
function parseData(data: unknown) {
  // data.name.toUpperCase(); // ❌ Error! Can't use unknown without check

  // Must narrow the type first:
  if (typeof data === 'object' && data !== null && 'name' in data) {
    console.log((data as { name: string }).name.toUpperCase()); // ✅ Safe!
  }
}

